ALTER TABLE products ADD COLUMN category_id uuid REFERENCES clinic_catalogs(id);
ALTER TABLE products ADD COLUMN brand_id uuid REFERENCES clinic_catalogs(id);
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),name text NOT NULL,kind text NOT NULL CHECK(kind IN ('person','company')),document text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',email text,notes text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE payables ADD COLUMN supplier_id uuid REFERENCES suppliers(id);
ALTER TABLE financial_categories ADD COLUMN dre_group text NOT NULL DEFAULT 'unclassified' CHECK(dre_group IN ('unclassified','service_revenue','product_revenue','tax','service_cost','product_cost','variable_cost','fixed_expense','depreciation','financial_result'));
ALTER TABLE receivables ADD COLUMN competence text;
ALTER TABLE receivables ADD COLUMN category_id uuid REFERENCES financial_categories(id);
ALTER TABLE receivables ADD COLUMN cost_center_id uuid REFERENCES cost_centers(id);
UPDATE receivables r SET competence=to_char(r.created_at AT TIME ZONE c.timezone,'YYYY-MM') FROM clinics c WHERE c.id=r.clinic_id;
ALTER TABLE payables ADD COLUMN dre_competence text;
UPDATE payables p SET dre_competence=coalesce(p.competence,to_char(p.created_at AT TIME ZONE c.timezone,'YYYY-MM')) FROM clinics c WHERE c.id=p.clinic_id;
CREATE TABLE patient_tab_services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),tab_id uuid NOT NULL REFERENCES patient_tabs(id),appointment_id uuid NOT NULL REFERENCES appointments(id),service_id uuid NOT NULL REFERENCES services(id),service_name text NOT NULL,professional_id uuid NOT NULL REFERENCES professionals(id),professional_name text NOT NULL,amount_in_cents integer NOT NULL CHECK(amount_in_cents>=0),UNIQUE(appointment_id));
CREATE INDEX patient_tab_services_tab_idx ON patient_tab_services(clinic_id,tab_id);
